var BANK_ACCOUNT_CODE = "class BankAccount:\n    def __init__(self, owner, balance=0):\n        self.owner = owner\n        self.balance = balance\n\n        def pay(self, amount):\n        if amount > 0:\n            self.balance += amount\n            print(f\"Счёт пополнен на {amount} тг\")\n        else:\n            print(\"Неправильная сумма\")\n\n        def withdraw(self, amount):\n        if amount <= 0:\n            print(\"Некорректная сумма\")\n        elif amount > self.balance:\n            print(\"Недостаточно средств\")\n        else:\n            self.balance -= amount\n            print(f\"Снято {amount} тг\")\n\n        def get_balance(self):\n        print(f\"Владелец: {self.owner}\")\n        print(f\"Баланс: {self.balance} тг\")\n\n        def transfer(self, other_account, amount):\n        if amount <= 0:\n            print(\"Некорректная сумма\")\n        elif amount > self.balance:\n            print(\"Недостаточно средств\")\n        else:\n            self.balance -= amount\n            other_account.balance += amount\n            print(f\"Переведено {amount} тг\")\n\n\naccount1 = BankAccount(\"Аким\", 10000)\naccount2 = BankAccount(\"Шайхим\", 5000)\n \naccount1.get_balance()\n\naccount1.pay(2000)\n\naccount1.withdraw(3000)\n\naccount1.transfer(account2, 1000)\n\nprint(\"\\nИтоговые балансы:\")\n\naccount1.get_balance()\naccount2.get_balance()";

