    "code": "class NonNegative:\n    def __init__(self, name):\n        self.name = name\n\n    def __get__(self, instance, owner):\n        if instance is None:\n            return self\n        return instance.__dict__.get(self.name, 0)\n\n    def __set__(self, instance, value):\n        if value < 0:\n            raise ValueError(f\"Атрибут '{self.name}' не может быть отрицательным!\")\n        instance.__dict__[self.name] = value\n\nclass Product:\n    price = NonNegative(\"price\")\n\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n\np = Product(\"Книга\", 1500)\nprint(f\"Товар: {p.name}, Цена: {p.price} тг\")\n\n# p.price = -100 # Вызовет ValueError!",
