    "code": "class RequireIdMeta(type):\n    def __new__(cls, name, bases, dct):\n        # Если это не базовый класс, проверяем наличие 'id' в атрибутах\n        if \"id\" not in dct:\n            raise TypeError(f\"Класс '{name}' обязан содержать атрибут 'id'!\")\n        return super().__new__(cls, name, bases, dct)\n\n# Успешный класс\nclass User(metaclass=RequireIdMeta):\n    id = 1\n    name = \"Арман\"\n\nprint(\"Класс User успешно создан с id =\", User.id)\n\n# Ошибочный класс (вызовет TypeError при объявлении):\n# class BadUser(metaclass=RequireIdMeta):\n#     name = \"Тест\"",
