    "code": "import sqlite3\n\nclass StudentDB:\n    def __init__(self, db_name=\"school.db\"):\n        self.conn = sqlite3.connect(db_name)\n        self.cursor = self.conn.cursor()\n        self.create_table()\n\n    def create_table(self):\n        self.cursor.execute(\"\"\"\n            CREATE TABLE IF NOT EXISTS students (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                name TEXT NOT NULL,\n                grade REAL NOT NULL\n            )\n        \"\"\")\n        self.conn.commit()\n\n    def add_student(self, name, grade):\n        self.cursor.execute(\"INSERT INTO students (name, grade) VALUES (?, ?)\", (name, grade))\n        self.conn.commit()\n        print(f\"Студент {name} добавлен.\")\n\n    def get_all_students(self):\n        self.cursor.execute(\"SELECT * FROM students\")\n        return self.cursor.fetchall()\n\n    def close(self):\n        self.conn.close()\n\n# Пример работы\ndb = StudentDB(\":memory:\")  # База в памяти для теста\ndb.add_student(\"Тимур\", 4.8)\ndb.add_student(\"Амина\", 5.0)\n\nfor s in db.get_all_students():\n    print(s)\ndb.close()",
