    "code": "class Product:\n    def __init__(self, product_id, name, price):\n        self.id = product_id\n        self.name = name\n        self.price = price\n\nclass Cart:\n    def __init__(self):\n        self.items = {}  # {product_id: {\"product\": obj, \"qty\": count}}\n\n    def add_product(self, product, qty=1):\n        if product.id in self.items:\n            self.items[product.id][\"qty\"] += qty\n        else:\n            self.items[product.id] = {\"product\": product, \"qty\": qty}\n        print(f\"Добавлено: {product.name} (x{qty})\")\n\n    def remove_product(self, product_id):\n        if product_id in self.items:\n            removed = self.items.pop(product_id)\n            print(f\"Удалено из корзины: {removed['product'].name}\")\n        else:\n            print(\"Товар не найден в корзине.\")\n\n    def total(self):\n        return sum(item[\"product\"].price * item[\"qty\"] for item in self.items.values())\n\n    def print_receipt(self):\n        print(\"\\n--- Чек покупки ---\")\n        for item in self.items.values():\n            p = item[\"product\"]\n            q = item[\"qty\"]\n            print(f\"{p.name} - {q} шт. x {p.price} = {p.price * q} тг\")\n        print(f\"ИТОГО К ОПЛАТЕ: {self.total()} тг\\n\")\n\n# Пример работы\np1 = Product(1, \"Клавиатура\", 12000)\np2 = Product(2, \"Наушники\", 25000)\n\ncart = Cart()\ncart.add_product(p1, 2)\ncart.add_product(p2, 1)\ncart.print_receipt()\n\ncart.remove_product(1)\ncart.print_receipt()",
